begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temp table cn_fx(k text primary key,id uuid,v jsonb);grant all on cn_fx to authenticated,service_role;
insert into cn_fx(k,id)select k,gen_random_uuid()from unnest(array['actor','other','session','other_session','job','attempt','cancel','configcancel','configsave','newtemplate','configcreate','configapprove','audio','transcribe','audio_note','audio_attempt','unclaimed_attempt','claimed_cancel_job','claimed_cancel_attempt','cancel_retry','retiredjob','retiredattempt','changedjob','changedattempt','retryjob','retryfirst','retrysecond'])k;
create function pg_temp.cn_id(key text)returns uuid language sql as $$select id from cn_fx where k=$1$$;
insert into auth.users(id,email,raw_user_meta_data)select id,'synthetic-note-'||id||'@example.test','{}'from cn_fx where k in('actor','other');
update profiles set is_active=true,full_name='Synthetic note staff'where id in(pg_temp.cn_id('actor'),pg_temp.cn_id('other'));
insert into user_roles(user_id,role)values(pg_temp.cn_id('actor'),'STAFF'),(pg_temp.cn_id('other'),'STAFF')on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)values(pg_temp.cn_id('session'),pg_temp.cn_id('actor'),now(),now()),(pg_temp.cn_id('other_session'),pg_temp.cn_id('other'),now(),now());
select ok(relrowsecurity and not has_table_privilege('authenticated',oid,'SELECT')and not has_table_privilege('authenticated',oid,'INSERT')and not has_table_privilege('service_role',oid,'SELECT'),relname||' private')from pg_class where relnamespace='public'::regnamespace and relname in('clinical_note_templates','clinical_note_template_versions','clinical_note_policies','clinical_note_configuration_actions','clinical_note_jobs','clinical_note_attempts','clinical_note_events','clinical_note_generations','clinical_note_reservation_cancellations','clinical_note_attempt_cancellations');
select ok(has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),proname||' guarded staff only')from pg_proc where pronamespace='public'::regnamespace and proname in('read_clinical_note_configuration','recover_clinical_note_configuration','cancel_clinical_note_configuration','save_clinical_note_configuration','read_clinical_notes','read_clinical_note_job','reserve_clinical_note','claim_clinical_note','read_clinical_note_provenance','cancel_clinical_note_reservation','list_clinical_note_template_versions','cancel_clinical_note_attempt');
select ok(has_function_privilege('service_role',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('authenticated',oid,'EXECUTE'),proname||' scoped worker only')from pg_proc where pronamespace='public'::regnamespace and proname in('dispatch_clinical_note','finish_clinical_note','fail_clinical_note');
select ok(not has_function_privilege('service_role',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('authenticated',oid,'EXECUTE'),proname||' owner only')from pg_proc where pronamespace='public'::regnamespace and proname in('clinical_note_nonblank','clinical_note_text_length','clinical_note_row_guard','clinical_note_validate_template','clinical_note_current_policy','clinical_note_template_list','clinical_note_job_view','clinical_note_guard','clinical_note_assemble');
select is((select status from clinical_note_policies where version=1),'draft','Typed processing starts inactive');
select is((select approved_version from clinical_note_templates where id='e7000000-0000-4000-8000-000000000001'),1,'Standard SOAP has fixed approved version');
select is((select approved_version from clinical_note_templates where id='e7000000-0000-4000-8000-000000000002'),null,'Susan structure remains draft');
select is((select status from clinical_audio_policies order by version desc limit 1),'draft','Existing audio policy unchanged');
insert into cn_fx(k,v)select 'definition',definition from clinical_note_template_versions where template_id='e7000000-0000-4000-8000-000000000001';
select is(clinical_note_nonblank(U&'\FEFF'),false,'BOM-only text is blank under ECMAScript trim semantics');
select is(clinical_note_nonblank(U&'\00A0'),false,'NBSP-only text is blank under ECMAScript trim semantics');
select is(clinical_note_nonblank(U&'\FEFF\00A0' || 'x' || U&'\2007'),true,'Nonblank Unicode content is preserved between ECMAScript whitespace');
select is(clinical_note_nonblank(U&'\0085'),true,'Unicode next-line is not ECMAScript trim whitespace');
select throws_ok($$select clinical_note_validate_template((select jsonb_set(v,'{name}',to_jsonb(U&'\FEFF'::text))from cn_fx where k='definition'))$$,'23514',null,'BOM-only template name cannot poison strict configuration reads');
select is(clinical_note_text_length('ASCII'),5,'UTF16 bound preserves ASCII length');
select is(clinical_note_text_length(U&'\+01F600'),2,'Supplementary Unicode character consumes two UTF16 units');
select is(clinical_note_text_length(U&'\00E9'),1,'BMP Unicode character consumes one UTF16 unit');
select is(clinical_note_text_length(repeat(U&'\+01F600',59)||'ab'),120,'Mixed Unicode text matches exact 120-unit browser boundary');
select throws_ok($$select clinical_note_validate_template((select jsonb_set(v,'{name}',to_jsonb(repeat(U&'\+01F600',100)))from cn_fx where k='definition'))$$,'23514',null,'Direct RPC cannot store an emoji name exceeding strict browser UTF16 bound');
select lives_ok($$select clinical_note_validate_template((select jsonb_set(v,'{name}',to_jsonb(repeat(U&'\+01F600',59)||'ab'))from cn_fx where k='definition'))$$,'Mixed Unicode template name accepted at exact browser unit boundary');
select throws_ok($$select clinical_note_validate_template((select jsonb_set(v,'{fields,0,instructions}',to_jsonb(repeat(U&'\+01F600',251)))from cn_fx where k='definition'))$$,'23514',null,'Instruction bound uses UTF16 units rather than codepoint count');
select throws_ok($$select clinical_note_validate_template((select v||'{"default_normal":"normal"}'from cn_fx where k='definition'))$$,'23514',null,'Factual default property rejected');
select throws_ok($$select clinical_note_validate_template((select jsonb_set(v,'{fields,0,destination}','"signature"')from cn_fx where k='definition'))$$,'23514',null,'Unsupported clinical destination rejected');
select throws_ok($$select clinical_note_validate_template((select jsonb_set(v,'{fields,1,id}','"subjective"')from cn_fx where k='definition'))$$,'23514',null,'Duplicate field identity rejected');
select throws_ok($$select clinical_note_validate_template((select jsonb_set(v,'{fields,0,instructions}',to_jsonb(repeat('x',501)))from cn_fx where k='definition'))$$,'23514',null,'Field instruction budget bounded');
select throws_ok($$select clinical_note_validate_template((select jsonb_set(v,'{name}',to_jsonb(repeat(' ',121)||'x'))from cn_fx where k='definition'))$$,'23514',null,'Raw template name bound matches strict browser schema');
select throws_ok($$select clinical_note_validate_template((select jsonb_set(v,'{fields,0,label}',to_jsonb(repeat(' ',121)||'x'))from cn_fx where k='definition'))$$,'23514',null,'Raw field label bound matches strict browser schema');
select throws_ok($$select clinical_note_validate_template((select jsonb_set(v,'{name}',to_jsonb(E'\n\t'::text))from cn_fx where k='definition'))$$,'23514',null,'Whitespace-only template name rejected');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.cn_id('actor'),'session_id',pg_temp.cn_id('session'))::text,true);
set local role authenticated;
insert into cn_fx(k,id)select 'client',id from save_client(auth.uid(),null,null,'Synthetic','Notes','+13035555581','synthetic-notes@example.test','EMAIL',null,null);
insert into cn_fx(k,id)select 'pet',id from save_patient(null,pg_temp.cn_id('client'),null,'Synthetic Notes','Dog','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into cn_fx(k,id)select 'other_pet',id from save_patient(null,pg_temp.cn_id('client'),null,'Other Synthetic','Dog','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into cn_fx(k,id)select 'encounter',id from save_clinical_encounter(null,pg_temp.cn_id('pet'),null,now(),'clinic','Synthetic clinic','Original history','Original exam','Original assessment','Original plan');
insert into cn_fx(k,v)select 'request',jsonb_build_object('pet_id',pg_temp.cn_id('pet'),'encounter_id',pg_temp.cn_id('encounter'),'expected_version',1,'policy_version',1,'template_id','e7000000-0000-4000-8000-000000000001','template_version',1,'template_hash',(read_clinical_note_configuration(auth.uid())#>>'{templates,0,approved,sha256}'),'source_kind','typed','source_text','Owner reports cough for two days. Eyes were not examined. Bloodwork declined. No medications administered.','audio_job_id',null,'source_note','Synthetic typed clinician observations','attest_authorized',true);
select throws_ok($$select reserve_clinical_note(auth.uid(),pg_temp.cn_id('job'),(select v from cn_fx where k='request'))$$,'42501',null,'Typed source cannot override draft policy');
select throws_ok($$select read_clinical_notes(pg_temp.cn_id('other'),pg_temp.cn_id('pet'),pg_temp.cn_id('encounter'))$$,'42501',null,'Actor spoof rejected');
select throws_ok($$select read_clinical_notes(auth.uid(),pg_temp.cn_id('other_pet'),pg_temp.cn_id('encounter'))$$,'23514',null,'Wrong patient read rejected');
select throws_ok($$select save_clinical_note_configuration(auth.uid(),gen_random_uuid(),'policy','{"expected_version":1,"status":"approved","consent_text":"Synthetic only","attest_reviewed":true}')$$,'42501',null,'Staff cannot approve practice settings');
reset role;insert into user_roles(user_id,role)values(pg_temp.cn_id('actor'),'ADMIN')on conflict do nothing;set local role authenticated;
select throws_ok($$select save_clinical_note_configuration(auth.uid(),gen_random_uuid(),'policy','{"expected_version":1,"status":"approved","consent_text":"Synthetic only","attest_reviewed":false}')$$,'23514',null,'Policy approval needs explicit review');
select is(save_clinical_note_configuration(auth.uid(),pg_temp.cn_id('configsave'),'policy','{"expected_version":1,"status":"approved","consent_text":"Synthetic LOCAL TEST policy, not practice clinical approval","attest_reviewed":true}')#>>'{configuration,policy,status}','approved','Explicit admin-reviewed synthetic policy admitted');
select is(recover_clinical_note_configuration(auth.uid(),pg_temp.cn_id('configsave'),'policy','{"expected_version":1,"status":"approved","consent_text":"Synthetic LOCAL TEST policy, not practice clinical approval","attest_reviewed":true}')#>>'{configuration,policy,version}','2','Lost configuration response recovers exact original version');
select is(save_clinical_note_configuration(auth.uid(),pg_temp.cn_id('configsave'),'policy','{"expected_version":1,"status":"approved","consent_text":"Synthetic LOCAL TEST policy, not practice clinical approval","attest_reviewed":true}')#>>'{configuration,policy,version}','2','Exact configuration retry does not append policy');
select throws_ok($$select save_clinical_note_configuration(auth.uid(),pg_temp.cn_id('configsave'),'policy','{"expected_version":1,"status":"approved","consent_text":"Changed","attest_reviewed":true}')$$,'23505',null,'Configuration UUID cannot be reused for changed work');
select is(cancel_clinical_note_configuration(auth.uid(),pg_temp.cn_id('configcancel'),'retire_template','{"template_id":"e7000000-0000-4000-8000-000000000001","expected_revision":1,"reason":"Synthetic abandoned"}')->>'cancelled','true','Uncommitted settings action cancelled durably');
select throws_ok($$select save_clinical_note_configuration(auth.uid(),pg_temp.cn_id('configcancel'),'retire_template','{"template_id":"e7000000-0000-4000-8000-000000000001","expected_revision":1,"reason":"Synthetic abandoned"}')$$,'PT409',null,'Late settings request blocked after cancellation');
update cn_fx set v=v||'{"policy_version":2}'where k='request';
select throws_ok($$select reserve_clinical_note(auth.uid(),gen_random_uuid(),(select v||'{"unexpected":true}'from cn_fx where k='request'))$$,'23514',null,'Unknown source keys rejected');
select throws_ok($$select reserve_clinical_note(auth.uid(),gen_random_uuid(),(select v||'{"attest_authorized":false}'from cn_fx where k='request'))$$,'23514',null,'Source attestation required');
select throws_ok($$select reserve_clinical_note(auth.uid(),gen_random_uuid(),(select v||jsonb_build_object('source_text',repeat(U&'\+01F600',30001))from cn_fx where k='request'))$$,'23514',null,'Typed source bound matches existing proposal reader UTF16 limit');
select throws_ok($$select reserve_clinical_note(auth.uid(),gen_random_uuid(),(select v||jsonb_build_object('pet_id',pg_temp.cn_id('other_pet'))from cn_fx where k='request'))$$,'PT409',null,'Wrong patient write rejected');
select throws_ok($$select reserve_clinical_note(auth.uid(),gen_random_uuid(),(select v||jsonb_build_object('template_hash',repeat('f',64))from cn_fx where k='request'))$$,'PT409',null,'Unknown template hash rejected');
select is(cancel_clinical_note_reservation(auth.uid(),pg_temp.cn_id('cancel'))->>'cancelled','true','Unsent reservation cancelled without persisting source');
select throws_ok($$select reserve_clinical_note(auth.uid(),pg_temp.cn_id('cancel'),(select v from cn_fx where k='request'))$$,'PT409',null,'Late reservation cannot recreate cancelled input');
insert into cn_fx(k,v)select 'reserved',reserve_clinical_note(auth.uid(),pg_temp.cn_id('job'),(select v from cn_fx where k='request'));
select is(reserve_clinical_note(auth.uid(),pg_temp.cn_id('job'),(select v from cn_fx where k='request')),(select v from cn_fx where k='reserved'),'Same source UUID recovers exact immutable reservation');
select throws_ok($$select reserve_clinical_note(auth.uid(),pg_temp.cn_id('job'),(select v||'{"source_text":"Changed source"}'from cn_fx where k='request'))$$,'23505',null,'Reserved source identity cannot change');
select is(cancel_clinical_note_reservation(auth.uid(),pg_temp.cn_id('job'))->>'cancelled','false','Cancel after commit recovers saved job');
select is(read_clinical_note_job(auth.uid(),pg_temp.cn_id('job'))#>>'{job,source_kind}','typed','Typed source remains distinctly attributed');
select ok(not(read_clinical_note_job(auth.uid(),pg_temp.cn_id('job'))->'job'?'session_id'),'Private originating session excluded from staff view');
-- A rejected request before claim must have a durable exit without sending the provider call.
select is(cancel_clinical_note_attempt(auth.uid(),pg_temp.cn_id('unclaimed_attempt'),pg_temp.cn_id('job'))->>'cancelled','true','Missing provider attempt cancelled durably');
select is(cancel_clinical_note_attempt(auth.uid(),pg_temp.cn_id('unclaimed_attempt'),pg_temp.cn_id('job'))->>'cancelled','true','Repeated missing-attempt cancellation is idempotent');
select throws_ok($$select claim_clinical_note(auth.uid(),pg_temp.cn_id('unclaimed_attempt'),pg_temp.cn_id('job'))$$,'PT409',null,'Late original claim rejected by cancellation tombstone');
select throws_ok($$select cancel_clinical_note_attempt(auth.uid(),pg_temp.cn_id('unclaimed_attempt'),pg_temp.cn_id('job'),null,'Changed intent',false)$$,'23505',null,'Cancellation UUID retains exact attempt intent');
select reserve_clinical_note(auth.uid(),pg_temp.cn_id('claimed_cancel_job'),(select v from cn_fx where k='request'));
select claim_clinical_note(auth.uid(),pg_temp.cn_id('claimed_cancel_attempt'),pg_temp.cn_id('claimed_cancel_job'));
select is(cancel_clinical_note_attempt(auth.uid(),pg_temp.cn_id('claimed_cancel_attempt'),pg_temp.cn_id('claimed_cancel_job'))->>'cancelled','true','Claimed but undispatched attempt cancelled safely');
select is(read_clinical_note_job(auth.uid(),pg_temp.cn_id('claimed_cancel_job'))#>>'{job,attempts,0,error_code}','operator_cancelled_before_dispatch','Claimed cancellation retains explicit no-dispatch failure reason');
select throws_ok($$select claim_clinical_note(auth.uid(),pg_temp.cn_id('claimed_cancel_attempt'),pg_temp.cn_id('claimed_cancel_job'))$$,'PT409',null,'Late original claim cannot revive canceled claimed attempt');
reset role;set local role service_role;
select is(dispatch_clinical_note(pg_temp.cn_id('claimed_cancel_attempt')),false,'Claim cancellation wins dispatch race and prevents provider admission');
reset role;set local role authenticated;
select is(claim_clinical_note(auth.uid(),pg_temp.cn_id('cancel_retry'),pg_temp.cn_id('claimed_cancel_job'),pg_temp.cn_id('claimed_cancel_attempt'),'Explicit canceled retry',true)->>'state','claimed','Explicit new attempt can retry canceled claim');
select is(cancel_clinical_note_attempt(auth.uid(),pg_temp.cn_id('cancel_retry'),pg_temp.cn_id('claimed_cancel_job'),pg_temp.cn_id('claimed_cancel_attempt'),'Explicit canceled retry',true)->>'cancelled','true','Explicit retry cancellation compares complete original intent');
insert into cn_fx(k,v)select 'claimed',claim_clinical_note(auth.uid(),pg_temp.cn_id('attempt'),pg_temp.cn_id('job'));
select is(claim_clinical_note(auth.uid(),pg_temp.cn_id('attempt'),pg_temp.cn_id('job')),(select v from cn_fx where k='claimed'),'Same attempt UUID recovers exact claim');
select throws_ok($$select claim_clinical_note(auth.uid(),gen_random_uuid(),pg_temp.cn_id('job'),pg_temp.cn_id('attempt'),'Retry',true)$$,'PT409',null,'Live attempt cannot be superseded');
reset role;set local role service_role;
select is(dispatch_clinical_note(pg_temp.cn_id('attempt')),true,'Provider dispatch admitted exactly once');
select is(dispatch_clinical_note(pg_temp.cn_id('attempt')),false,'Duplicate dispatch cannot cause provider resend');
reset role;set local role authenticated;
select is(cancel_clinical_note_attempt(auth.uid(),pg_temp.cn_id('attempt'),pg_temp.cn_id('job'))->>'cancelled','false','Sending outcome cannot be canceled or declared unsent');
select is(read_clinical_note_job(auth.uid(),pg_temp.cn_id('job'))#>>'{job,attempts,0,state}','sending','Sending attempt remains recoverable unchanged');
reset role;set local role service_role;

insert into cn_fx(k,v)values('payload','{"fields":[{"field_id":"subjective","status":"supported","claims":[{"text":"Owner reports cough for two days.","quote":"Owner reports cough for two days."}],"uncertainty":""},{"field_id":"objective","status":"missing","claims":[],"uncertainty":""},{"field_id":"assessment","status":"missing","claims":[],"uncertainty":""},{"field_id":"plan","status":"supported","claims":[{"text":"Bloodwork declined; no medications administered.","quote":"Bloodwork declined. No medications administered."}],"uncertainty":""}],"review_flags":["Eyes were not examined."]}');
insert into cn_fx(k,v)select 'result',jsonb_build_object('request_id','synthetic-request','response_id','synthetic-response','provider_model','gpt-6-luna','contract_version','clinical-note-v1','prompt_version','lrv-note-fields-v1','source_sha256',(select v->>'source_sha256'from cn_fx where k='reserved'),'template_sha256',(select v->>'template_hash'from cn_fx where k='reserved'),'language_context',jsonb_build_object('version','lrv-vet-en-v1','bundle_sha256',repeat('a',64),'request_sha256',repeat('b',64)),'payload',(select v from cn_fx where k='payload'));
select throws_ok($$select finish_clinical_note(pg_temp.cn_id('attempt'),(select jsonb_set(v,'{payload,fields,0,claims,0,quote}','"Unspoken normal"')from cn_fx where k='result'))$$,'23514',null,'Invented source quote rejected');
select throws_ok($$select finish_clinical_note(pg_temp.cn_id('attempt'),(select jsonb_set(v,'{payload,fields,0,field_id}','"eyes"')from cn_fx where k='result'))$$,'23514',null,'Unknown or reordered field rejected');
select throws_ok($$select finish_clinical_note(pg_temp.cn_id('attempt'),(select jsonb_set(v,'{payload,fields,0,destination}','"objective"')from cn_fx where k='result'))$$,'23514',null,'Provider cannot inject SOAP destination');
select throws_ok($$select finish_clinical_note(pg_temp.cn_id('attempt'),(select jsonb_set(v,'{payload,fields,1,status}','"supported"')from cn_fx where k='result'))$$,'23514',null,'Missing source cannot become supported finding');
select throws_ok($$select finish_clinical_note(pg_temp.cn_id('attempt'),(select v||jsonb_build_object('source_sha256',repeat('f',64))from cn_fx where k='result'))$$,'23514',null,'Result pinned to immutable source hash');
select throws_ok($$select finish_clinical_note(pg_temp.cn_id('attempt'),(select v||'{"prompt_version":"different"}'from cn_fx where k='result'))$$,'23514',null,'Unknown prompt version rejected');
select is(finish_clinical_note(pg_temp.cn_id('attempt'),(select v from cn_fx where k='result'))->>'proposal_id',pg_temp.cn_id('attempt')::text,'Validated fields create existing reviewed proposal');
select is(finish_clinical_note(pg_temp.cn_id('attempt'),(select v from cn_fx where k='result'))->>'proposal_id',pg_temp.cn_id('attempt')::text,'Lost result acknowledgement recovers without provider request');
select throws_ok($$select finish_clinical_note(pg_temp.cn_id('attempt'),(select v||'{"request_id":"changed"}'from cn_fx where k='result'))$$,'23505',null,'Completed result identity cannot change');
reset role;
select is((select sections#>>'{objective,text}'from clinical_dictation_proposals where id=pg_temp.cn_id('attempt')),'','Missing exam stays empty without default normals');
select is((select sections#>>'{subjective,text}'from clinical_dictation_proposals where id=pg_temp.cn_id('attempt')),E'Subjective:\nOwner reports cough for two days.','Assembly uses pinned template label and order');
select is((select subjective from clinical_encounters where id=pg_temp.cn_id('encounter')),'Original history','Generation does not modify chart');
select throws_ok($$update clinical_note_template_versions set definition='{}'where template_id='e7000000-0000-4000-8000-000000000001'$$,'23514',null,'Template versions immutable');
select throws_ok($$truncate clinical_note_generations$$,'23514',null,'Generation provenance cannot be truncated');
set local role authenticated;
select is(read_clinical_note_provenance(auth.uid(),pg_temp.cn_id('attempt'))#>>'{payload,fields,0,claims,0,quote}','Owner reports cough for two days.','Every original field quote retained in provenance');
select is(read_clinical_note_provenance(auth.uid(),pg_temp.cn_id('attempt'))->>'source_kind','typed','Provenance distinguishes typed observations');
select is(cancel_clinical_note_attempt(auth.uid(),pg_temp.cn_id('attempt'),pg_temp.cn_id('job'))->>'cancelled','false','Completed generation remains original outcome when cancel requested');

-- A separate draft template can be edited, approved, and retired without rewriting its versions.
select save_clinical_note_configuration(auth.uid(),pg_temp.cn_id('configcreate'),'create_template',jsonb_build_object('template_id',pg_temp.cn_id('newtemplate'),'definition',(select v||'{"name":"Synthetic review template"}'from cn_fx where k='definition')));
select throws_ok($$select reserve_clinical_note(auth.uid(),gen_random_uuid(),(select v||jsonb_build_object('template_id',pg_temp.cn_id('newtemplate'))from cn_fx where k='request'))$$,'PT409',null,'Draft template cannot generate');
insert into cn_fx(k,v)select 'newhash',to_jsonb((select x->'latest'->>'sha256'from jsonb_array_elements(read_clinical_note_configuration(auth.uid())->'templates')x where x->>'id'=pg_temp.cn_id('newtemplate')::text));
select save_clinical_note_configuration(auth.uid(),pg_temp.cn_id('configapprove'),'approve_template',jsonb_build_object('template_id',pg_temp.cn_id('newtemplate'),'expected_revision',1,'version',1,'sha256',(select v#>>'{}'from cn_fx where k='newhash'),'attest_reviewed',true));
select reserve_clinical_note(auth.uid(),pg_temp.cn_id('retiredjob'),(select v||jsonb_build_object('template_id',pg_temp.cn_id('newtemplate'),'template_hash',(select v#>>'{}'from cn_fx where k='newhash'))from cn_fx where k='request'));
select claim_clinical_note(auth.uid(),pg_temp.cn_id('retiredattempt'),pg_temp.cn_id('retiredjob'));
select save_clinical_note_configuration(auth.uid(),gen_random_uuid(),'save_template',jsonb_build_object('template_id',pg_temp.cn_id('newtemplate'),'expected_revision',2,'definition',(select v||'{"name":"Synthetic second version"}'from cn_fx where k='definition')));
select is(list_clinical_note_template_versions(auth.uid(),pg_temp.cn_id('newtemplate'))->'versions'->0->>'version','2','Template edit creates separate immutable version');
select is(read_clinical_note_job(auth.uid(),pg_temp.cn_id('retiredjob'))#>>'{template,status}','approved','Unapproved new draft leaves approved version usable');
select save_clinical_note_configuration(auth.uid(),gen_random_uuid(),'retire_template',jsonb_build_object('template_id',pg_temp.cn_id('newtemplate'),'expected_revision',3,'reason','Synthetic retirement'));
reset role;set local role service_role;
select throws_ok($$select dispatch_clinical_note(pg_temp.cn_id('retiredattempt'))$$,'PT409',null,'Retirement blocks saved work before provider dispatch');
select fail_clinical_note(pg_temp.cn_id('retiredattempt'),false,'template_retired');
reset role;set local role authenticated;
select is(read_clinical_note_job(auth.uid(),pg_temp.cn_id('retiredjob'))#>>'{template,definition,name}','Synthetic review template','Old job retains original template after editing and retirement');
-- Retry is explicit and bounded, with provider cooldown and immutable uncertain outcome.
select reserve_clinical_note(auth.uid(),pg_temp.cn_id('retryjob'),(select v from cn_fx where k='request'));
select claim_clinical_note(auth.uid(),pg_temp.cn_id('retryfirst'),pg_temp.cn_id('retryjob'));
reset role;set local role service_role;
select fail_clinical_note(pg_temp.cn_id('retryfirst'),true,'provider_outcome_unknown','{"retry_after_seconds":60}');
reset role;set local role authenticated;
select throws_ok($$select claim_clinical_note(auth.uid(),pg_temp.cn_id('retrysecond'),pg_temp.cn_id('retryjob'))$$,'23514',null,'Unknown provider outcome never autoresends');
select throws_ok($$select claim_clinical_note(auth.uid(),pg_temp.cn_id('retrysecond'),pg_temp.cn_id('retryjob'),pg_temp.cn_id('retryfirst'),'Explicit retry',true)$$,'PT409',null,'Provider cooldown honored');
reset role;update clinical_note_attempts set finished_at=clock_timestamp()-interval'2 minutes'where id=pg_temp.cn_id('retryfirst');set local role authenticated;
select is(claim_clinical_note(auth.uid(),pg_temp.cn_id('retrysecond'),pg_temp.cn_id('retryjob'),pg_temp.cn_id('retryfirst'),'Explicit retry',true)->>'state','claimed','Explicit cost-acknowledged retry admitted after cooldown');
reset role;select is((select state from clinical_note_attempts where id=pg_temp.cn_id('retryfirst')),'superseded','Earlier outcome retained as superseded attempt');
-- Original staff-session revocation prevents worker dispatch.
delete from auth.sessions where id=pg_temp.cn_id('session');set local role service_role;
select throws_ok($$select dispatch_clinical_note(pg_temp.cn_id('retrysecond'))$$,'42501',null,'Revoked originating session blocks dispatch');
reset role;
insert into auth.sessions(id,user_id,created_at,updated_at)values(pg_temp.cn_id('session'),pg_temp.cn_id('actor'),now(),now());
-- Audio transcript adapter uses the existing completed source, never a supplied transcription.
insert into clinical_audio_policies(version,status,consent_text,audio_retention,transcript_retention,transcription_model,soap_model,reviewed_by,reviewed_at)values(2,'approved','Synthetic LOCAL TEST policy, not practice approval','not_stored','Synthetic test retention','gpt-transcribe','gpt-6-luna',pg_temp.cn_id('actor'),now());
set local role authenticated;
select reserve_clinical_audio(auth.uid(),pg_temp.cn_id('audio'),jsonb_build_object('pet_id',pg_temp.cn_id('pet'),'encounter_id',pg_temp.cn_id('encounter'),'expected_version',1,'policy_version',2,'sha256',repeat('c',64),'frames',16000,'byte_size',32044,'source_note','Synthetic source','attest_authorized',true));
select claim_clinical_audio(auth.uid(),pg_temp.cn_id('transcribe'),pg_temp.cn_id('audio'),'transcribe');
reset role;set local role service_role;
select dispatch_clinical_audio(pg_temp.cn_id('transcribe'));
select finish_clinical_audio(pg_temp.cn_id('transcribe'),jsonb_build_object('request_id','synthetic-transcription','response_id','','provider_model','','contract_version','clinical-audio-v1','payload',jsonb_build_object('text',(select v->>'source_text'from cn_fx where k='request'))));
reset role;set local role authenticated;
insert into cn_fx(k,v)select 'audio_request',v||jsonb_build_object('source_kind','audio_transcript','source_text',null,'audio_job_id',pg_temp.cn_id('audio'))from cn_fx where k='request';
select throws_ok($$select reserve_clinical_note(auth.uid(),gen_random_uuid(),(select v||'{"source_text":"Forged transcript"}'from cn_fx where k='audio_request'))$$,'23514',null,'Audio adapter rejects supplied transcript');
select is(reserve_clinical_note(auth.uid(),pg_temp.cn_id('audio_note'),(select v from cn_fx where k='audio_request'))->>'source_kind','audio_transcript','Completed audio source enters separate template generation lane');
select is(read_clinical_note_job(auth.uid(),pg_temp.cn_id('audio_note'))#>>'{job,source_audio_policy_version}','2','Audio source policy version pinned');
select claim_clinical_note(auth.uid(),pg_temp.cn_id('audio_attempt'),pg_temp.cn_id('audio_note'));
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.cn_id('other'),'session_id',pg_temp.cn_id('other_session'))::text,true);
select throws_ok($$select reserve_clinical_note(auth.uid(),gen_random_uuid(),(select v from cn_fx where k='audio_request'))$$,'42501',null,'Other operator cannot reattribute recorded source');
select throws_ok($$select claim_clinical_note(auth.uid(),gen_random_uuid(),pg_temp.cn_id('audio_note'))$$,'42501',null,'Other operator cannot process an owned job');
select throws_ok($$select cancel_clinical_note_attempt(auth.uid(),pg_temp.cn_id('attempt'),pg_temp.cn_id('job'))$$,'42501',null,'Other operator cannot cancel a saved generation attempt');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.cn_id('actor'),'session_id',pg_temp.cn_id('session'))::text,true);
reset role;
insert into clinical_audio_policies(version,status,consent_text,audio_retention,transcript_retention,transcription_model,soap_model)values(3,'draft','Synthetic policy re-review','not_stored','Synthetic retention','gpt-transcribe','gpt-6-luna');
set local role service_role;
select throws_ok($$select dispatch_clinical_note(pg_temp.cn_id('audio_attempt'))$$,'42501',null,'Typed approval does not bypass revised audio policy');
reset role;
insert into clinical_audio_policies(version,status,consent_text,audio_retention,transcript_retention,transcription_model,soap_model,reviewed_by,reviewed_at)values(4,'approved','Synthetic policy reapproval','not_stored','Synthetic retention','gpt-transcribe','gpt-6-luna',pg_temp.cn_id('actor'),now());
set local role service_role;
select throws_ok($$select dispatch_clinical_note(pg_temp.cn_id('audio_attempt'))$$,'42501',null,'Newer approved audio policy does not relabel old source authorization');
reset role;set local role authenticated;
select save_clinical_dictation_action(auth.uid(),gen_random_uuid(),'review',jsonb_build_object('pet_id',pg_temp.cn_id('pet'),'encounter_id',pg_temp.cn_id('encounter'),'expected_version',1,'proposal_id',pg_temp.cn_id('attempt'),'decision','accepted','accepted_sections',jsonb_build_object('subjective','Reviewed cough history.'),'review_note','Synthetic explicit review','attest_reviewed',true));
select is((select subjective from clinical_encounters where id=pg_temp.cn_id('encounter')),'Reviewed cough history.','Existing reviewed write path accepts explicitly selected content');
select is((select objective from clinical_encounters where id=pg_temp.cn_id('encounter')),'Original exam','Unselected clinical sections preserved');
select throws_ok($$select reserve_clinical_note(auth.uid(),gen_random_uuid(),(select v from cn_fx where k='request'))$$,'PT409',null,'Stale encounter generation rejected');
select is(read_clinical_note_provenance(auth.uid(),pg_temp.cn_id('attempt'))#>>'{template_snapshot,definition,name}','Standard SOAP','Provenance remains readable after chart version advances');
select is(cancel_clinical_note_attempt(auth.uid(),gen_random_uuid(),pg_temp.cn_id('job'))->>'cancelled','true','Unclaimed attempt can be canceled after destination version changes');

reset role;set local role service_role;
select throws_ok($$select dispatch_clinical_note(pg_temp.cn_id('retrysecond'))$$,'PT409',null,'Destination change blocks provider dispatch');
reset role;set local role authenticated;
select save_clinical_note_configuration(auth.uid(),gen_random_uuid(),'policy','{"expected_version":2,"status":"draft","consent_text":"Synthetic policy needs re-review","attest_reviewed":false}');
select is(cancel_clinical_note_attempt(auth.uid(),gen_random_uuid(),pg_temp.cn_id('job'))->>'cancelled','true','Stale source remains cancelable when processing policy is disabled');

reset role;
select *from finish();rollback;
